/**
 * Local Vite toolchain for the playground SPA.
 *
 * Published installs ship `dist/playground/` and do not need this — vite is a
 * devDependency and `playground/` sources may be absent. In a monorepo / source
 * checkout, `serve` uses this to auto-build a missing bundle and (with `--dev`)
 * spawn the Vite HMR server.
 */
import { spawn } from "node:child_process";
import { existsSync, readFileSync } from "node:fs";
import { createRequire } from "node:module";
import { dirname, join } from "node:path";
import { fileURLToPath } from "node:url";
import { isRecord } from "../is-record.js";
import { playgroundBundleExists } from "./static.js";
function packageBin(value, name, fallback) {
    if (!isRecord(value)) {
        return fallback;
    }
    if (typeof value.bin === "string") {
        return value.bin;
    }
    if (isRecord(value.bin) && typeof value.bin[name] === "string") {
        return value.bin[name];
    }
    return fallback;
}
const VITE_CONFIG = "playground/vite.config.ts";
/** Package root (works from `src/` or `dist/`). */
export function packageRoot() {
    // src|dist/internal/playground/toolchain.ts → packages/agent-serve/
    return fileURLToPath(new URL("../../..", import.meta.url));
}
/** Resolve the absolute path to vite's CLI bin without using blocked package exports. */
function resolveViteCli(root) {
    try {
        const require = createRequire(join(root, "package.json"));
        let dir = dirname(require.resolve("vite"));
        for (let i = 0; i < 6; i++) {
            const pkgPath = join(dir, "package.json");
            if (existsSync(pkgPath)) {
                const parsed = JSON.parse(readFileSync(pkgPath, "utf8"));
                if (isRecord(parsed) && parsed.name === "vite") {
                    const binRel = packageBin(parsed, "vite", "bin/vite.js");
                    const binAbs = join(dir, binRel);
                    return existsSync(binAbs) ? binAbs : undefined;
                }
            }
            const parent = dirname(dir);
            if (parent === dir) {
                break;
            }
            dir = parent;
        }
    }
    catch {
        return undefined;
    }
    return undefined;
}
/** True when playground sources + a resolvable `vite` CLI are present. */
export function resolvePlaygroundToolchain() {
    const root = packageRoot();
    const viteConfig = join(root, VITE_CONFIG);
    if (!existsSync(viteConfig)) {
        return undefined;
    }
    const viteCli = resolveViteCli(root);
    if (viteCli === undefined) {
        return undefined;
    }
    return { packageRoot: root, viteCli, viteConfig };
}
export function playgroundToolchainAvailable() {
    return resolvePlaygroundToolchain() !== undefined;
}
/**
 * `AGENT_SERVE_BASE` for the Vite proxy when serving a single slugged agent.
 * Multi-agent serve uses path-based HMR (`/<slug>/playground`) unless the
 * caller pins one slug via {@link playgroundDevBaseFromEnv}.
 */
export function playgroundDevBasePath(mounts) {
    if (mounts.length === 1 && mounts[0]?.slug !== "") {
        return `/${mounts[0].slug}`;
    }
    return undefined;
}
/**
 * Optional pin for multi-agent Vite HMR (SPA at root, rewrite `/v1` → base).
 * Empty / unset → multi-agent path mode (`AGENT_SERVE_MULTI`).
 */
export function playgroundDevBaseFromEnv(env = process.env) {
    const raw = env.AGENT_SERVE_BASE?.trim();
    if (raw === undefined || raw === "") {
        return undefined;
    }
    const normalized = raw.replace(/\/+$/, "");
    if (normalized === "" || normalized === "/") {
        return undefined;
    }
    return normalized.startsWith("/") ? normalized : `/${normalized}`;
}
/** Run `vite build` for the playground; throws on non-zero exit. */
export async function runPlaygroundBuild(logger = console.log) {
    const toolchain = resolvePlaygroundToolchain();
    if (toolchain === undefined) {
        throw new Error("playground vite toolchain unavailable (need playground/ sources and the vite package)");
    }
    logger("[bdk] building playground (vite)...");
    const code = await spawnVite(toolchain, ["build", "--config", VITE_CONFIG], {
        env: process.env,
    });
    if (code !== 0) {
        throw new Error(`playground vite build failed (exit ${code})`);
    }
    if (!playgroundBundleExists()) {
        throw new Error("playground vite build finished but dist/playground/index.html is missing");
    }
    logger("[bdk] playground build complete");
}
/**
 * If the SPA bundle is missing and the local toolchain is available, build it.
 * No-op when the bundle already exists. Soft-skips (logs) when vite is absent
 * so published installs without a prebuilt bundle still start.
 */
export async function ensurePlaygroundBundle(logger = console.log) {
    if (playgroundBundleExists()) {
        return;
    }
    if (resolvePlaygroundToolchain() === undefined) {
        logger("[bdk] playground bundle missing and vite toolchain unavailable; /playground will show a build hint");
        return;
    }
    await runPlaygroundBuild(logger);
}
/**
 * Spawn Vite HMR for the playground, proxying API calls at {@link targetUrl}.
 * Multi-agent mode serves `/<slug>/playground` + the agents index at `/`.
 * Returns undefined when the toolchain is unavailable.
 */
export function startPlaygroundDevServer(options) {
    const logger = options.logger ?? console.log;
    const toolchain = resolvePlaygroundToolchain();
    if (toolchain === undefined) {
        return undefined;
    }
    const port = playgroundDevPort();
    const multiAgent = options.multiAgent === true;
    const env = {
        ...process.env,
        AGENT_SERVE_PLAYGROUND_PORT: String(port),
        AGENT_SERVE_TARGET: options.targetUrl,
    };
    if (multiAgent) {
        env.AGENT_SERVE_MULTI = "1";
        delete env.AGENT_SERVE_BASE;
    }
    else {
        delete env.AGENT_SERVE_MULTI;
        if (options.basePath !== undefined && options.basePath !== "") {
            env.AGENT_SERVE_BASE = options.basePath;
        }
        else {
            delete env.AGENT_SERVE_BASE;
        }
    }
    // Quiet + isolated from the TTY: the serve banner owns the terminal.
    // Piped stdio keeps Vite from seeing a TTY (so it cannot clearScreen), and
    // silent logging drops the "VITE ready" / URL spam. Errors still surface via
    // spawn/exit handlers below.
    const child = spawn(process.execPath, [toolchain.viteCli, "--config", VITE_CONFIG, "--logLevel", "silent"], {
        cwd: toolchain.packageRoot,
        env,
        stdio: ["ignore", "ignore", "pipe"],
    });
    child.stderr?.on("data", (chunk) => {
        const text = chunk.toString().trimEnd();
        if (text !== "") {
            logger(`[bdk] playground: ${text}`);
        }
    });
    let stopped = false;
    child.on("error", (err) => {
        if (stopped) {
            return;
        }
        logger(`[bdk] playground spawn failed: ${err.message} — static /playground still served when built`);
    });
    child.on("exit", (code, signal) => {
        if (stopped) {
            return;
        }
        if (code !== 0 && code !== null) {
            logger(`[bdk] playground exited (code ${code}${signal ? `, signal ${signal}` : ""}) — static /playground still served when built`);
        }
    });
    return {
        url: `http://127.0.0.1:${port}/`,
        stop: () => {
            stopped = true;
            if (!child.killed) {
                child.kill("SIGTERM");
            }
        },
    };
}
export function playgroundDevPort() {
    const parsed = Number(process.env.AGENT_SERVE_PLAYGROUND_PORT ?? "5273");
    if (!Number.isInteger(parsed) || parsed <= 0 || parsed > 65535) {
        return 5273;
    }
    return parsed;
}
function spawnVite(toolchain, args, options) {
    return new Promise((resolve, reject) => {
        const child = spawn(process.execPath, [toolchain.viteCli, ...args], {
            cwd: toolchain.packageRoot,
            env: options.env,
            stdio: "inherit",
        });
        child.on("error", reject);
        child.on("exit", (code) => {
            resolve(code ?? 1);
        });
    });
}
